const rotateAngle = 45;

const getPercent = (current: number, full: number) => {
  return (current * 1) / full;
};

export const moveShadow = (angle: number) => {
  angle = ((angle % 360) + 360) % 360;
  const coordinates = { x: 0, y: 0 };
  console.log(" angle:", angle);

  if (angle > 270) {
    const current = angle - 270;
    coordinates.x = getPercent(current, 90);
  } else if (angle > 180) {
    const current = angle - 180;

    coordinates.x = (1 - getPercent(current, 90)) * -1;
  } else if (angle > 90) {
    const current = angle - 90;
    coordinates.x = getPercent(current, 90) * -1;
    coordinates.y = getPercent(current, 90);
  } else {
    coordinates.x = 1 - getPercent(angle, 90);
    coordinates.y = getPercent(angle, 90);
  }

  console.log(coordinates);
  return coordinates;
};
